import sys
from collections import defaultdict

def read_ints():
    return list(map(int, sys.stdin.readline().strip().split()))

def main():
    t = int(sys.stdin.readline().strip())
    for _ in range(t):
        n = int(sys.stdin.readline().strip())
        edges = [read_ints() for _ in range(n - 1)]

        # Create a graph from the edges
        graph = defaultdict(list)
        for u, v in edges:
            graph[u].append(v)
            graph[v].append(u)

        # Find the degree of each node
        degree = {node: len(neighbors) for node, neighbors in graph.items()}

        # Find the node with the maximum degree
        max_degree_node = max(degree, key=degree.get)

        # Create a list to store the relabeling
        relabeling = [0] * n

        # Assign the nodes based on their degree and potential for maximizing the XOR condition
        current_label = 1
        for node in sorted(degree, key=lambda x: (-degree[x], x)):
            if relabeling[node - 1] == 0:
                relabeling[node - 1] = current_label
                current_label += 1

        # Print the relabeling
        print(' '.join(map(str, relabeling)))

if __name__ == "__main__":
    main()
